def truncate_number(number: float) -> float:
    """
    Return the decimal part of a positive floating point number.
    Raises TypeError if the input is not numeric.
    Raises ValueError if the input is not a positive finite number.
    """
    if not isinstance(number, (int, float)):
        raise TypeError("Input must be a numeric type.")
    number = float(number)
    if number != number or number == float('inf') or number == -float('inf'):
        raise ValueError("Input must be a finite number.")
    if number <= 0:
        raise ValueError("Input must be a positive number.")
    return number - int(number)

def mean_absolute_deviation(numbers: List[float]) -> float:
    try:
        nums = list(numbers)
    except TypeError:
        raise ValueError("Input must be an iterable of numbers")
    if not nums:
        raise ValueError("The list of numbers must not be empty")
    try:
        mean = sum(nums) / len(nums)
    except TypeError:
        raise ValueError("All elements must be numeric")
    mad = sum(abs(x - mean) for x in nums) / len(nums)
    return mad

