def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string must consist only of decimal digits.
    Raises ValueError for invalid inputs.
    """
    # Basic type and value checks
    if not isinstance(num_str, str):
        raise TypeError("num_str must be a string")
    if not isinstance(N, int) or not isinstance(K, int):
        raise TypeError("N and K must be integers")
    if len(num_str) != N:
        raise ValueError("Length of num_str does not match N")
    if N == 0:
        return 0
    if K < 0 or K > N - 1:
        raise ValueError("K must be between 0 and N-1 inclusive")
    if not num_str.isdigit():
        raise ValueError("num_str must contain only digits")

    # Special case: no multiplication signs
    if K == 0:
        return int(num_str)

    # Precompute integer values for all substrings num_str[i:j]
    val = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        num = 0
        for j in range(i, N):
            num = num * 10 + (ord(num_str[j]) - 48)
            val[i][j + 1] = num

    # DP table: dp[i][k] = max product for first i digits with k multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: k = 0
    for i in range(1, N + 1):
        dp[i][0] = val[0][i]

    # Fill DP
    for k in range(1, K + 1):
        # i must be at least k+1 to have k+1 parts
        for i in range(k + 1, N + 1):
            max_prod = 0
            # j is the split point: first part ends at j, second part starts at j
            # j must be at least k (since dp[j][k-1] requires at least k digits)
            for j in range(k, i):
                prod = dp[j][k - 1] * val[j][i]
                if prod > max_prod:
                    max_prod = prod
            dp[i][k] = max_prod

    return dp[N][K]

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    # Basic validation
    if not (isinstance(M, int) and M > 0 and isinstance(N, int) and N > 0):
        raise ValueError("M and N must be positive integers.")
    if not (isinstance(K, int) and K >= 0 and isinstance(L, int) and L >= 0):
        raise ValueError("K and L must be non‑negative integers.")
    if not (isinstance(D, int) and D >= 0):
        raise ValueError("D must be a non‑negative integer.")
    if not isinstance(chatting_pairs, list):
        raise ValueError("chatting_pairs must be a list.")
    if D != len(chatting_pairs):
        raise ValueError("Length of chatting_pairs does not match D.")
    # Cap K and L to available positions
    max_rows = M - 1
    max_cols = N - 1
    K = min(K, max_rows)
    L = min(L, max_cols)

    # Convert pairs to list of tuples of coordinates
    pairs = []
    for p in chatting_pairs:
        if not (isinstance(p, tuple) and len(p) == 4):
            raise ValueError("Each chatting pair must be a tuple of four integers.")
        x1, y1, x2, y2 = p
        if not (1 <= x1 <= M and 1 <= x2 <= M and 1 <= y1 <= N and 1 <= y2 <= N):
            raise ValueError("Pair coordinates out of bounds.")
        pairs.append((x1, y1, x2, y2))

    # Set of indices of pairs not yet separated
    remaining = set(range(len(pairs)))

    selected_rows = []
    selected_cols = []

    # Helper functions to compute marginal benefit
    def row_separation(row):
        count = 0
        for idx in remaining:
            x1, _, x2, _ = pairs[idx]
            if (x1 <= row < x2) or (x2 <= row < x1):
                count += 1
        return count

    def col_separation(col):
        count = 0
        for idx in remaining:
            _, y1, _, y2 = pairs[idx]
            if (y1 <= col < y2) or (y2 <= col < y1):
                count += 1
        return count

    # Main greedy loop
    while len(selected_rows) < K or len(selected_cols) < L:
        best_row = None
        best_row_val = -1
        if len(selected_rows) < K:
            for r in range(1, M):
                if r in selected_rows:
                    continue
                val = row_separation(r)
                if val > best_row_val:
                    best_row_val = val
                    best_row = r

        best_col = None
        best_col_val = -1
        if len(selected_cols) < L:
            for c in range(1, N):
                if c in selected_cols:
                    continue
                val = col_separation(c)
                if val > best_col_val:
                    best_col_val = val
                    best_col = c

        # Decide which aisle to add
        if best_row_val > best_col_val:
            # Add row
            selected_rows.append(best_row)
            # Remove separated pairs
            to_remove = set()
            for idx in remaining:
                x1, _, x2, _ = pairs[idx]
                if (x1 <= best_row < x2) or (x2 <= best_row < x1):
                    to_remove.add(idx)
            remaining -= to_remove
        elif best_col_val > best_row_val:
            # Add column
            selected_cols.append(best_col)
            to_remove = set()
            for idx in remaining:
                _, y1, _, y2 = pairs[idx]
                if (y1 <= best_col < y2) or (y2 <= best_col < y1):
                    to_remove.add(idx)
            remaining -= to_remove
        else:
            # Tie or both zero
            if best_row is not None:
                selected_rows.append(best_row)
                to_remove = set()
                for idx in remaining:
                    x1, _, x2, _ = pairs[idx]
                    if (x1 <= best_row < x2) or (x2 <= best_row < x1):
                        to_remove.add(idx)
                remaining -= to_remove
            elif best_col is not None:
                selected_cols.append(best_col)
                to_remove = set()
                for idx in remaining:
                    _, y1, _, y2 = pairs[idx]
                    if (y1 <= best_col < y2) or (y2 <= best_col < y1):
                        to_remove.add(idx)
                remaining -= to_remove
            else:
                # No more possible aisles
                break

    # Sort results
    selected_rows.sort()
    selected_cols.sort()

    row_str = ' '.join(str(r) for r in selected_rows)
    col_str = ' '.join(str(c) for c in selected_cols)
    return (row_str, col_str)

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        TypeError: If inputs are of incorrect type.
        ValueError: If n is negative or coeffs length does not match n+1.
    """
    # Validate input types
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(coeffs, list):
        raise TypeError("coeffs must be a list")
    if n < 0:
        raise ValueError("n must be non-negative")
    if len(coeffs) != n + 1:
        raise ValueError("coeffs length must be n + 1")
    for c in coeffs:
        if not isinstance(c, int):
            raise TypeError("All coefficients must be integers")

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic type and length checks
    if not isinstance(encoded, str) or not isinstance(original, str) or not isinstance(message, str):
        return "Failed"
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse = {}
    for e, o in zip(encoded, original):
        # Check forward mapping consistency
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o
        # Check reverse mapping consistency (bijective requirement)
        if o in reverse:
            if reverse[o] != e:
                return "Failed"
        else:
            reverse[o] = e

    # Ensure all 26 uppercase letters are represented in the mapping
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest
    common divisor (GCD) and y0 as their least common multiple (LCM).

    Args:
        x0 (int): The GCD that each pair (P, Q) must have.
        y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
        int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    # Validate inputs
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 < x0:
        return 0
    if y0 % x0 != 0:
        return 0

    # Helper function for gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    n = y0 // x0
    count = 0
    limit = int(n ** 0.5)
    for a in range(1, limit + 1):
        if n % a == 0:
            b = n // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def string_transformation(A: str, B: str, rules: list):
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps or "NO ANSWER!" if impossible.
    """
    # Basic input validation
    if not isinstance(A, str) or not isinstance(B, str):
        raise TypeError("A and B must be strings.")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list.")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise ValueError("Each rule must be a tuple of two elements.")
        if not isinstance(rule[0], str) or not isinstance(rule[1], str):
            raise ValueError("Rule elements must be strings.")
    # Immediate success
    if A == B:
        return 0
    from collections import deque
    max_steps = 10
    visited = {A}
    queue = deque([(A, 0)])
    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Basic type validation
    if not isinstance(scenario, str):
        raise TypeError("scenario must be a string")
    if not isinstance(liar_count, set):
        raise TypeError("liar_count must be a set")
    if not isinstance(statements, dict):
        raise TypeError("statements must be a dict")
    if not isinstance(days_of_week, set):
        raise TypeError("days_of_week must be a set")

    # Normalize names to upper case for comparison
    scenario_upper = scenario.upper()
    liar_names = {name.upper() for name in liar_count}
    days_lower = {day.lower() for day in days_of_week}

    for speaker, stmts in statements.items():
        if not isinstance(speaker, str):
            raise TypeError("participant names must be strings")
        if not isinstance(stmts, list):
            raise TypeError("statements for each participant must be a list")
        speaker_upper = speaker.upper()
        is_liar = speaker_upper in liar_names

        for stmt in stmts:
            if not isinstance(stmt, str):
                raise TypeError("each statement must be a string")
            stmt_clean = stmt.strip()
            if not stmt_clean:
                continue

            # Ignore statements about days of the week
            words = [w.strip(".,!?;:").lower() for w in stmt_clean.split()]
            if any(day in words for day in days_lower):
                continue

            # Determine subject and guilt flag
            stmt_lower = stmt_clean.lower()
            subject = None
            guilty_flag = None

            if stmt_lower.startswith("i am "):
                subject = speaker_upper
                if "not guilty" in stmt_lower:
                    guilty_flag = False
                elif "guilty" in stmt_lower:
                    guilty_flag = True
            else:
                # Expect format: "<NAME> is guilty." or "<NAME> is not guilty."
                if " is " in stmt_lower:
                    parts = stmt_lower.split(" is ", 1)
                    if len(parts) == 2:
                        subject_name = parts[0].strip().upper()
                        rest = parts[1].strip()
                        if "not guilty" in rest:
                            guilty_flag = False
                        elif "guilty" in rest:
                            guilty_flag = True
                        subject = subject_name

            # If we couldn't parse the statement, skip it
            if subject is None or guilty_flag is None:
                continue

            # Evaluate truth of the statement
            truth = (subject == scenario_upper) == guilty_flag

            # Check consistency with liar status
            if is_liar and truth:
                return False
            if not is_liar and not truth:
                return False

    return True

